 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    original = [row[:] for row in g]

    # Each contiguous nonzero run of length >= 2 is a motif/template.
    motifs = []
    for row in original:
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start >= 2:
                motif = row[start:c]
                if motif not in motifs:
                    motifs.append(motif)

    # A single cell between zeros marks a position in one of the motifs.
    # Expand each marker by copying its matching motif, aligned on that color.
    for r, row in enumerate(original):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start != 1:
                continue
            marker_col = start
            color = row[start]
            candidates = [motif for motif in motifs if color in motif]
            if not candidates:
                continue
            motif = candidates[0]
            aligned_start = marker_col - motif.index(color)
            for i, value in enumerate(motif):
                x = aligned_start + i
                if 0 <= x < w:
                    g[r][x] = value
    return g
